INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v1', 1, 'Fill', 'Mix beans, cumin, half the cheese. Spread on tortillas, top with cheese, fold.', '["black beans","shredded cheese"]');
