INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 'rcp_crispy-fish-tacos-cabbage-slaw', 'crispy-fish-tacos-cabbage-slaw', 2, 'Crispy Fish Tacos with Cabbage Slaw', 'Cornmeal-crusted pan-fried cod in corn tortillas with a cabbage-carrot slaw and dairy-free crema.', 4, 15, 20, 35, 'Easy', 'none', 'Crust golden. Cod opaque, flakes easily, 145 F in the center of a strip. Not chalky.', '["stovetop"]', '["dairy-free"]', '{"crema":"Store-bought dairy-free crema, or 1/2 cup vegan mayo plus the juice of 1/2 lime. Do not use sour cream or yogurt.","soy":"Some vegan mayos and dairy-free cremas contain soy. Soy is not a confirmed allergen until the brand is known."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, 'a7a3ddc84180cbb4866689f1e7723293454ae8701b927406f6329db0ca688292', 'flavorweave-legacy-catalog-package', 'catalog/crispy-fish-tacos-cabbage-slaw/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 'rcp_crispy-skillet-chicken-sandwiches', 'crispy-skillet-chicken-sandwiches', 1, 'Crispy Skillet Chicken Sandwiches', 'Pound-thin chicken cutlets seared in a skillet and stacked on rolls with lemon-dijon mayonnaise, lettuce, and tomato.', 4, 12, 16, 28, 'weeknight', 'Skillet over medium-high; lower to medium only if the crust darkens before the center is done.', '165°F in the center of each cutlet. Color is not the doneness test.', '[]', '[]', 'null', '[{"component_id":"lemon-dijon-mayonnaise","name":"lemon-dijon mayonnaise","made_in_recipe":true,"store_bought":false,"built_from_store_bought":["mayonnaise","dijon mustard"],"ingredients":["mayonnaise","dijon mustard","lemon","fresh parsley","garlic","kosher salt"]}]', 'published', 'draft', 'global', NULL, '73d7df15f282e692ec98693b3006e2fc1f8ad81884d6f2af11d4fa25896de293', 'flavorweave-catalog-package', 'catalog/crispy-skillet-chicken-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_garlic-tomato-mussels_v1', 'rcp_garlic-tomato-mussels', 'garlic-tomato-mussels', 1, 'Garlic Tomato Mussels with Grilled Bread', 'Mussels steamed in a garlic and crushed-tomato broth, finished with parsley and lemon, with oil-brushed bread toasted in a skillet.', 4, 15, 13, 28, 'weeknight', 'Medium for the onion and garlic, then a 4-minute simmer, then medium-high under a lid for the mussels. Bread toasts over medium-high.', 'Mussels are done when the shells open, usually 4 to 6 minutes. Discard any that stay closed. Do not cook them until they shrink.', '[]', '[]', 'null', '[{"component_id":"tomato-garlic-broth","name":"tomato garlic broth","made_in_recipe":true,"store_bought":false,"note":"Built in the pot from the listed aromatics, canned crushed tomatoes, and dry white wine. Those two store-bought inputs are labeled on the ingredients. There is no separate bottled sauce.","ingredients":["olive oil","onion","garlic","red pepper flakes","crushed tomatoes","dry white wine","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '2b17dbd634803c9c8d3c3c2da8ce6c95e53d96c34df5e9ef9d10cbcf367e2cee', 'flavorweave-catalog-package', 'catalog/garlic-tomato-mussels/v1.json', '2026-10-04T00:00:00.000Z');
