INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-scallion-fish-packets_v2', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 2, 'Ginger Scallion Fish Packets', 'Foil packets of white fish and halved bok choy with ginger, scallion, and soy, baked until the fish flakes, served with rice.', 4, 15, 20, 35, 'Easy', 'Oven 400 F for the packets. Rice simmers, covered, on the stove and overlaps the bake.', 'Fish flakes easily and is opaque in the center, 18 to 20 minutes at 400 F. Bok choy is tender. Rice is tender and the water is absorbed. Not a rare fillet and not a sear.', '["oven","stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '74b4b53dff88c4203b6e8227e879445be8572950d3ca430e8c77423276f83b72', 'flavorweave-legacy-audit-draft', 'catalog/ginger-scallion-fish-packets/v2.json', '2026-10-04T00:00:00.000Z');
